import{_ as t,o as a,c as s,a2 as i}from"./chunks/framework.ecJ-2P1q.js";const u=JSON.parse('{"title":"MCP Quickstart","description":"","frontmatter":{},"headers":[],"relativePath":"operations/mcp-quickstart.md","filePath":"operations/mcp-quickstart.md"}'),n={name:"operations/mcp-quickstart.md"};function o(r,e,l,h,d,p){return a(),s("div",null,[...e[0]||(e[0]=[i(`<h1 id="mcp-quickstart" tabindex="-1">MCP Quickstart <a class="header-anchor" href="#mcp-quickstart" aria-label="Permalink to &quot;MCP Quickstart&quot;">​</a></h1><p>By the end of this page, an AI assistant such as Claude will have built a small workflow for you and saved it as a file, and you&#39;ll have opened that file in the Aerini desktop app. It takes about 15 minutes, and you don&#39;t need a server, an API key or a token.</p><p><strong>You&#39;ll need:</strong> the Aerini desktop app, and either Claude Code or Claude Desktop. If you use another MCP client that starts local programs, the same steps work; see <a href="./mcp#other-clients">Other clients</a>.</p><h2 id="what-this-is-in-one-minute" tabindex="-1">What this is, in one minute <a class="header-anchor" href="#what-this-is-in-one-minute" aria-label="Permalink to &quot;What this is, in one minute&quot;">​</a></h2><p>An AI assistant can&#39;t see or change anything on your computer by itself. <strong>MCP</strong> (Model Context Protocol) is a standard way to hand it a small, fixed set of tools. <code>aerini-mcp</code> is the small program that provides Aerini&#39;s tools:</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span> You  -&gt;  AI client (Claude Code,   -&gt;  aerini-mcp-offline  -&gt;  a .aerini file</span></span>
<span class="line"><span>          Claude Desktop, ...)          (starts and stops with    in ~/aerini-workflows</span></span>
<span class="line"><span>                                         the client)</span></span></code></pre></div><p>In this tutorial you use the <strong>offline</strong> build. It can look up which nodes exist, check a workflow for mistakes, and write the result to a file. It cannot run anything, reach a network or change anything except one folder. That makes it the safe way to try MCP.</p><h2 id="step-1-download-the-program" tabindex="-1">Step 1: Download the program <a class="header-anchor" href="#step-1-download-the-program" aria-label="Permalink to &quot;Step 1: Download the program&quot;">​</a></h2><ol><li>Open the <a href="https://github.com/Panchak2d/aerini/releases" target="_blank" rel="noreferrer">Releases page</a>.</li><li>Find the <strong>MCP server</strong> table in the release notes, and download the <strong>Offline</strong> archive for your computer, plus the <code>.sha256</code> file with the same name.</li></ol><p>The file name must start with <code>aerini-mcp-offline_</code>. A name that starts with <code>Aerini_</code> is the desktop app, which you don&#39;t need here. If you&#39;re unsure which platform is yours, <a href="./mcp-install#step-2-match-the-platform-to-your-computer">Install the MCP Program</a> shows how to check.</p><h2 id="step-2-verify-and-unpack-it" tabindex="-1">Step 2: Verify and unpack it <a class="header-anchor" href="#step-2-verify-and-unpack-it" aria-label="Permalink to &quot;Step 2: Verify and unpack it&quot;">​</a></h2><p>Put both files in one folder, then check that the download is intact. On Linux:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sha256sum</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -c</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aerini-mcp-offline_0.4.3_x86_64-unknown-linux-gnu.tar.gz.sha256</span></span></code></pre></div><p>You want to see <code>OK</code> after the file name. The macOS and Windows commands are in <a href="./mcp-install#step-4-verify-the-download">Step 4 of the install page</a>. The examples use version <code>0.4.3</code>; use the one you downloaded.</p><p>Then unpack it into a folder of its own (Linux and macOS):</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">mkdir</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -p</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/aerini-mcp</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">tar</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -xzf</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aerini-mcp-offline_0.4.3_x86_64-unknown-linux-gnu.tar.gz</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -C</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ~/aerini-mcp</span></span></code></pre></div><p>On Windows, use <code>Expand-Archive</code>; see <a href="./mcp-install#step-5-unpack-it-into-its-own-folder">Step 5</a>.</p><h2 id="step-3-clear-the-macos-or-windows-warning" tabindex="-1">Step 3: Clear the macOS or Windows warning <a class="header-anchor" href="#step-3-clear-the-macos-or-windows-warning" aria-label="Permalink to &quot;Step 3: Clear the macOS or Windows warning&quot;">​</a></h2><p>The programs aren&#39;t code-signed, so your system may refuse to start them the first time.</p><ul><li><strong>macOS:</strong> run <code>xattr -d com.apple.quarantine ~/aerini-mcp/aerini-mcp-offline</code> once. If it says the attribute doesn&#39;t exist, carry on.</li><li><strong>Windows:</strong> if SmartScreen appears, click <strong>More info</strong>, then <strong>Run anyway</strong>.</li></ul><h2 id="step-4-check-that-it-starts" tabindex="-1">Step 4: Check that it starts <a class="header-anchor" href="#step-4-check-that-it-starts" aria-label="Permalink to &quot;Step 4: Check that it starts&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">~</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">/aerini-mcp/aerini-mcp-offline --version</span></span></code></pre></div><p>It prints the program&#39;s name and version. Then write down the <strong>full path</strong> of the program, because clients don&#39;t search your <code>PATH</code>. On Linux and macOS, <code>realpath ~/aerini-mcp/aerini-mcp-offline</code> prints it. On Windows, <code>(Resolve-Path $HOME\\aerini-mcp\\aerini-mcp-offline.exe).Path</code> does.</p><h2 id="step-5-register-it-with-your-client" tabindex="-1">Step 5: Register it with your client <a class="header-anchor" href="#step-5-register-it-with-your-client" aria-label="Permalink to &quot;Step 5: Register it with your client&quot;">​</a></h2><p>Pick the client you use.</p><h3 id="claude-code" tabindex="-1">Claude Code <a class="header-anchor" href="#claude-code" aria-label="Permalink to &quot;Claude Code&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> mcp</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --transport</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stdio</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> aerini</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /full/path/to/aerini-mcp-offline</span></span></code></pre></div><p>Check it with <code>claude mcp list</code>, or type <code>/mcp</code> inside a Claude Code session. Aerini should be listed.</p><h3 id="claude-desktop" tabindex="-1">Claude Desktop <a class="header-anchor" href="#claude-desktop" aria-label="Permalink to &quot;Claude Desktop&quot;">​</a></h3><ol><li><p>Open <strong>Settings → Developer → Edit Config</strong>.</p></li><li><p>Add the server under <code>mcpServers</code>. If the file already has servers, add yours beside them; don&#39;t paste a second <code>mcpServers</code> block.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;mcpServers&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;aerini&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;command&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/full/path/to/aerini-mcp-offline&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;args&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;--out-dir&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/full/path/to/a/folder/for/saved/workflows&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div></li><li><p>Use absolute paths. On Windows, double every backslash: <code>C:\\\\Users\\\\you\\\\aerini-mcp\\\\aerini-mcp-offline.exe</code>.</p></li><li><p><strong>Quit Claude Desktop completely</strong> and open it again. On macOS, closing the window leaves the app running with the old configuration.</p></li></ol><p>Claude Desktop starts the program from a folder you don&#39;t control, which is why the example sets <code>--out-dir</code> to an absolute path.</p><h2 id="step-6-ask-for-a-workflow" tabindex="-1">Step 6: Ask for a workflow <a class="header-anchor" href="#step-6-ask-for-a-workflow" aria-label="Permalink to &quot;Step 6: Ask for a workflow&quot;">​</a></h2><p>Start a new chat (or a new Claude Code session) and ask something small and concrete:</p><blockquote><p>List the Aerini nodes that can send an HTTP request. Then build a workflow with a manual trigger and one HTTP Request node that fetches <code>https://example.com</code>, validate it, and save it.</p></blockquote><p>Your client asks you to approve each tool call the first time. Approve them. You should see the agent call <code>list_nodes</code>, <code>get_node_schema</code>, <code>validate_workflow</code> and <code>save_workflow</code>, and then tell you the path of the file it wrote. By default that&#39;s a <code>.aerini</code> file under <code>~/aerini-workflows</code>.</p><h2 id="step-7-open-it-in-aerini" tabindex="-1">Step 7: Open it in Aerini <a class="header-anchor" href="#step-7-open-it-in-aerini" aria-label="Permalink to &quot;Step 7: Open it in Aerini&quot;">​</a></h2><p>Open the desktop app and drag the saved <code>.aerini</code> file onto the canvas. On an empty canvas you can use the import button instead. Press <strong>Run</strong> to see it work. Importing always adds a new workflow, so it never overwrites one you already have.</p><p>You&#39;ve now done the whole loop: an agent designed a workflow, checked it, and handed it to you as a file.</p><h2 id="if-it-didn-t-work" tabindex="-1">If it didn&#39;t work <a class="header-anchor" href="#if-it-didn-t-work" aria-label="Permalink to &quot;If it didn&#39;t work&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you see</th><th>Most likely cause</th></tr></thead><tbody><tr><td>The client lists no Aerini tools</td><td>The path is wrong or relative, a Windows backslash isn&#39;t doubled, the JSON is invalid, or Claude Desktop wasn&#39;t fully quit.</td></tr><tr><td>macOS says the program can&#39;t be opened</td><td>The quarantine flag is set. Repeat Step 3.</td></tr><tr><td><code>Not written: ... already exists</code></td><td>A file with that name is already in the output folder. Ask the agent to save under a new workflow id.</td></tr></tbody></table><p>Run the program by hand to see its start-up error: <code>~/aerini-mcp/aerini-mcp-offline</code>. A healthy offline program prints nothing and waits for a client; press Ctrl+C to stop it. The full list of messages is in <a href="./mcp#troubleshooting">Troubleshooting</a>.</p><h2 id="where-next" tabindex="-1">Where next <a class="header-anchor" href="#where-next" aria-label="Permalink to &quot;Where next&quot;">​</a></h2><table tabindex="0"><thead><tr><th>You want to...</th><th>Go to</th></tr></thead><tbody><tr><td>Let the agent run workflows, not just draft them</td><td><a href="./mcp#choosing-a-mode">Choosing a mode</a>, then <a href="./mcp#setting-up-the-server-side">Setting up the server side</a></td></tr><tr><td>Understand what each switch and limit does</td><td><a href="./mcp">MCP Server for AI Agents</a></td></tr><tr><td>Teach your agent the right working order</td><td><a href="./../guide/agents">Building Workflows with an AI Agent</a></td></tr><tr><td>Know what to lock down before giving an agent write access</td><td><a href="./mcp#write-access-and-allow-write">Write access and <code>--allow-write</code></a> and <a href="./mcp#security">Security</a></td></tr></tbody></table><details class="details custom-block"><summary>For experienced users</summary><ul><li>The mode is chosen by the environment, not a flag: no <code>AERINI_URL</code> means offline, and offline exists only in the <code>aerini-mcp-offline</code> build.</li><li>Offline serves four tools: <code>list_nodes</code>, <code>get_node_schema</code>, <code>validate_workflow</code> and <code>save_workflow</code>. The other seven are listed and answer with an error that says how to enable them.</li><li><code>save_workflow</code> never overwrites unless the call passes <code>overwrite=true</code>, and unsafe characters in the workflow id become <code>_</code>.</li><li>Offline sees built-in nodes only, not plugin nodes. For the live catalog of a server, use online mode.</li><li><code>validate_workflow</code> is best effort: <code>valid: true</code> means no known structural problem, not that the run will succeed.</li></ul></details>`,44)])])}const k=t(n,[["render",o]]);export{u as __pageData,k as default};
